-- Generated from Fan's --seed-db native module schemas. No historical data.
CREATE TABLE app_file(path TEXT PRIMARY KEY,content TEXT NOT NULL DEFAULT '',modified_ts TEXT);
CREATE TABLE app_config(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE app (  id          INTEGER PRIMARY KEY AUTOINCREMENT,  app_key     TEXT NOT NULL UNIQUE,  exe         TEXT,  class       TEXT,  display     TEXT,  first_seen  TEXT,  last_seen   TEXT,  total_ms    INTEGER NOT NULL DEFAULT 0,  activations INTEGER NOT NULL DEFAULT 0);
CREATE TABLE app_setting (key TEXT PRIMARY KEY, value TEXT NOT NULL DEFAULT '');
CREATE TABLE appmap_app (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, exe TEXT DEFAULT '', cls TEXT DEFAULT '', title TEXT DEFAULT '', win_x INTEGER DEFAULT 0, win_y INTEGER DEFAULT 0, win_w INTEGER DEFAULT 0, win_h INTEGER DEFAULT 0, learned_ts TEXT DEFAULT '', notes TEXT DEFAULT '');
CREATE TABLE chrome_history_archive (  id              INTEGER PRIMARY KEY AUTOINCREMENT,  profile         TEXT NOT NULL,  source_visit_id INTEGER,  visit_time      INTEGER NOT NULL,  visited_ts      TEXT,  url             TEXT NOT NULL,  title           TEXT,  search_term     TEXT,  visit_count     INTEGER NOT NULL DEFAULT 0,  first_import_ts TEXT,  last_import_ts  TEXT,  UNIQUE(profile,visit_time,url));
CREATE TABLE clip_history (  id         INTEGER PRIMARY KEY AUTOINCREMENT,  win_id     INTEGER,  app_id     INTEGER,  ts         TEXT,  minute_key TEXT,  hash       TEXT,  length     INTEGER,  kind       TEXT,  content    TEXT);
CREATE TABLE discovered_target(id INTEGER PRIMARY KEY AUTOINCREMENT, app_key TEXT, title TEXT, topic TEXT, name TEXT, role TEXT, acc_path TEXT, x INTEGER,y INTEGER,w INTEGER,h INTEGER, rel_x REAL,rel_y REAL,rel_w REAL,rel_h REAL, shortcut TEXT, seen_count INTEGER DEFAULT 1, last_ts TEXT, UNIQUE(app_key,title,acc_path));
CREATE TABLE element (  id            INTEGER PRIMARY KEY AUTOINCREMENT,  win_id        INTEGER,  app_id        INTEGER,  snap_entry_id INTEGER,  name          TEXT NOT NULL,  description   TEXT,  role          TEXT,  x INTEGER, y INTEGER, w INTEGER, h INTEGER,  rel_x REAL, rel_y REAL, rel_w REAL, rel_h REAL,  bin_text      TEXT,  ocr_text      TEXT,  image_path    TEXT,  b64           TEXT,  created_ts    TEXT,  updated_ts    TEXT,  hits          INTEGER NOT NULL DEFAULT 0,  last_hit_ts   TEXT,  UNIQUE(win_id, name));
CREATE TABLE hotkey_stat (  win_id  INTEGER NOT NULL,  app_id  INTEGER NOT NULL,  combo   TEXT NOT NULL,  count   INTEGER NOT NULL DEFAULT 0,  last_ts TEXT,  PRIMARY KEY (win_id, combo));
CREATE TABLE key_event (  id         INTEGER PRIMARY KEY AUTOINCREMENT,  win_id     INTEGER NOT NULL REFERENCES win(id),  app_id     INTEGER NOT NULL,  ts         TEXT NOT NULL,  minute_key TEXT NOT NULL,  event_type TEXT NOT NULL,  detail     TEXT,  content    TEXT);
CREATE TABLE key_snapshot (  id          INTEGER PRIMARY KEY AUTOINCREMENT,  win_id      INTEGER NOT NULL REFERENCES win(id),  app_id      INTEGER NOT NULL,  minute_key  TEXT NOT NULL,  start_ts    TEXT,  end_ts      TEXT,  keystrokes  INTEGER NOT NULL DEFAULT 0,  raw_stream  TEXT,  text_typed  TEXT,  hotkeys     TEXT,  strings     TEXT,  sentences   TEXT,  code_snips  TEXT,  clips       TEXT,  wpm         REAL NOT NULL DEFAULT 0,  UNIQUE(win_id, minute_key));
CREATE TABLE media_image(id INTEGER PRIMARY KEY AUTOINCREMENT,label TEXT,data_url TEXT NOT NULL,created_ts TEXT);
CREATE TABLE meta (  key TEXT PRIMARY KEY,  value TEXT);
CREATE TABLE mouse_feature (  id        INTEGER PRIMARY KEY AUTOINCREMENT,  win_id    INTEGER NOT NULL REFERENCES win(id),  app_id    INTEGER NOT NULL,  kind      TEXT,  x INTEGER, y INTEGER, w INTEGER, h INTEGER,  rel_x REAL, rel_y REAL,  weight    REAL    NOT NULL DEFAULT 0,  samples   INTEGER NOT NULL DEFAULT 0,  clicks    INTEGER NOT NULL DEFAULT 0,  dwell_ms  INTEGER NOT NULL DEFAULT 0,  first_seen TEXT,  last_seen  TEXT,  element_id INTEGER);
CREATE TABLE mouse_heat (  win_id   INTEGER NOT NULL REFERENCES win(id),  gx       INTEGER NOT NULL,  gy       INTEGER NOT NULL,  hits     INTEGER NOT NULL DEFAULT 0,  clicks   INTEGER NOT NULL DEFAULT 0,  dwell_ms INTEGER NOT NULL DEFAULT 0,  PRIMARY KEY (win_id, gx, gy));
CREATE TABLE mouse_snapshot (  id           INTEGER PRIMARY KEY AUTOINCREMENT,  win_id       INTEGER NOT NULL REFERENCES win(id),  app_id       INTEGER NOT NULL,  minute_key   TEXT NOT NULL,  start_ts     TEXT,  end_ts       TEXT,  samples      INTEGER NOT NULL DEFAULT 0,  distance     REAL    NOT NULL DEFAULT 0,  idle_ms      INTEGER NOT NULL DEFAULT 0,  dwell_count  INTEGER NOT NULL DEFAULT 0,  click_count  INTEGER NOT NULL DEFAULT 0,  win_x INTEGER, win_y INTEGER, win_w INTEGER, win_h INTEGER,  path_blob    TEXT,  click_blob   TEXT,  UNIQUE(win_id, minute_key));
CREATE TABLE ocr_fix (id INTEGER PRIMARY KEY AUTOINCREMENT,wrong TEXT NOT NULL, right TEXT NOT NULL,hits INTEGER DEFAULT 1, last_ts TEXT,UNIQUE(wrong, right));
CREATE TABLE ocr_log (id INTEGER PRIMARY KEY AUTOINCREMENT, ts TEXT, text TEXT, word_count INTEGER);
CREATE TABLE patterns (name TEXT PRIMARY KEY, text TEXT, desc TEXT, screenshot TEXT, captureX INTEGER, captureY INTEGER, captureWindow TEXT, qualifier TEXT);
CREATE TABLE qa_item (id INTEGER PRIMARY KEY AUTOINCREMENT,created_ts TEXT, snip_id INTEGER, source_image TEXT,ordinal TEXT, kind TEXT, label TEXT,question TEXT NOT NULL, choices TEXT, blanks INTEGER DEFAULT 0,section TEXT DEFAULT '',answer TEXT DEFAULT '', answered_ts TEXT,correct_tags TEXT DEFAULT '',shown INTEGER DEFAULT 0, last_shown_ts TEXT,skipped INTEGER DEFAULT 0, archived INTEGER DEFAULT 0,fingerprint TEXT, state TEXT DEFAULT 'candidate', confidence REAL DEFAULT 0, answer_source TEXT DEFAULT '', provider TEXT DEFAULT '', model TEXT DEFAULT '', evidence TEXT DEFAULT '', verified_ts TEXT DEFAULT '');
CREATE TABLE query (  id         INTEGER PRIMARY KEY AUTOINCREMENT,  text       TEXT NOT NULL,  engine     TEXT,  created_ts TEXT,  status     TEXT,  note       TEXT);
CREATE TABLE query_insight (  id         INTEGER PRIMARY KEY AUTOINCREMENT,  query_id   INTEGER NOT NULL REFERENCES query(id),  link_id    INTEGER,  insight    TEXT,  source     TEXT,  created_ts TEXT);
CREATE TABLE query_link (  id         INTEGER PRIMARY KEY AUTOINCREMENT,  query_id   INTEGER NOT NULL REFERENCES query(id),  rank       INTEGER,  url        TEXT,  title      TEXT,  status     TEXT,  visited_ts TEXT,  created_ts TEXT);
CREATE TABLE sequence_steps (seq_name TEXT, step_index INTEGER, action TEXT, target TEXT, param TEXT, enabled INTEGER, failsafe TEXT, qual_pattern TEXT, qual_window TEXT, PRIMARY KEY (seq_name, step_index));
CREATE TABLE sequences (name TEXT PRIMARY KEY, speed REAL, hotkey TEXT, hotstring TEXT);
CREATE TABLE snap_cycle (  id           INTEGER PRIMARY KEY AUTOINCREMENT,  started_ts   TEXT,  finished_ts  TEXT,  window_count INTEGER NOT NULL DEFAULT 0,  note         TEXT);
CREATE TABLE snap_entry (  id           INTEGER PRIMARY KEY AUTOINCREMENT,  cycle_id     INTEGER NOT NULL REFERENCES snap_cycle(id),  win_id       INTEGER,  app_id       INTEGER,  hwnd         INTEGER,  title        TEXT,  exe          TEXT,  class        TEXT,  ts           TEXT,  x INTEGER, y INTEGER, w INTEGER, h INTEGER,  image_path   TEXT,  image_format TEXT,  image_bytes  INTEGER,  image_hash   TEXT,  b64          TEXT,  b64_len      INTEGER,  bin_text     TEXT,  bin_w        INTEGER,  bin_h        INTEGER,  threshold    TEXT,  ocr_text     TEXT,  url          TEXT,  url_source   TEXT,  search_query TEXT,  visual_signature TEXT,  is_excluded  INTEGER NOT NULL DEFAULT 0,  exclusion_reason TEXT);
CREATE TABLE snap_exclusion (  id            INTEGER PRIMARY KEY AUTOINCREMENT,  kind          TEXT NOT NULL,  signature     TEXT,  tolerance     INTEGER NOT NULL DEFAULT 5,  exe           TEXT,  class         TEXT,  title_pattern TEXT,  note          TEXT,  active        INTEGER NOT NULL DEFAULT 1,  created_ts    TEXT,  match_count   INTEGER NOT NULL DEFAULT 0,  last_match_ts TEXT);
CREATE TABLE snip (id INTEGER PRIMARY KEY AUTOINCREMENT,ts TEXT, x INTEGER, y INTEGER, w INTEGER, h INTEGER,image_path TEXT, signature TEXT,ocr_raw TEXT,ocr_text TEXT,accepted INTEGER DEFAULT 0,corrected INTEGER DEFAULT 0,variant TEXT, note TEXT);
CREATE TABLE snip_setting (key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE spools (name TEXT PRIMARY KEY, enabled INTEGER, region TEXT, regionCoords TEXT, detectType TEXT, target TEXT, interval INTEGER, condition TEXT, action TEXT, actionTarget TEXT, extractOCR INTEGER, ocrVar TEXT, autoComplete INTEGER, completion TEXT, completionTarget TEXT, timeout INTEGER, mode TEXT, cooldown INTEGER, notifTime INTEGER);
CREATE TABLE study_answer_log (id INTEGER PRIMARY KEY AUTOINCREMENT,qa_id INTEGER, ts TEXT, state TEXT DEFAULT 'candidate',answer TEXT DEFAULT '', source TEXT DEFAULT '',provider TEXT DEFAULT '', model TEXT DEFAULT '',confidence REAL DEFAULT 0, evidence TEXT DEFAULT '',escalation_reason TEXT DEFAULT '', cost REAL DEFAULT 0, choices_snapshot TEXT DEFAULT '', question_snapshot TEXT DEFAULT '');
CREATE TABLE study_concept (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL, norm_name TEXT DEFAULT '', definition TEXT DEFAULT '',kind TEXT DEFAULT 'concept', importance INTEGER DEFAULT 0,source_id INTEGER DEFAULT 0, page INTEGER DEFAULT 0,seen INTEGER DEFAULT 1, created_ts TEXT, last_ts TEXT);
CREATE TABLE study_concept_link (id INTEGER PRIMARY KEY AUTOINCREMENT,from_id INTEGER, to_id INTEGER, relation TEXT DEFAULT 'related',weight INTEGER DEFAULT 1);
CREATE TABLE study_passage (id INTEGER PRIMARY KEY AUTOINCREMENT,source_id INTEGER, ordinal INTEGER DEFAULT 0, page INTEGER DEFAULT 0,heading TEXT DEFAULT '', text TEXT NOT NULL, norm TEXT DEFAULT '',created_ts TEXT);
CREATE TABLE study_review (qa_id INTEGER PRIMARY KEY, ease REAL DEFAULT 2.5,interval_days INTEGER DEFAULT 0, reps INTEGER DEFAULT 0,due_ts TEXT, last_ts TEXT, last_grade INTEGER DEFAULT 0);
CREATE TABLE study_setting (key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE study_source (id INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT, title TEXT, path TEXT DEFAULT '',course TEXT DEFAULT '', topic TEXT DEFAULT '',added_ts TEXT, bytes INTEGER DEFAULT 0, pages INTEGER DEFAULT 0,version INTEGER DEFAULT 1, excluded INTEGER DEFAULT 0);
CREATE TABLE ui_element (id INTEGER PRIMARY KEY AUTOINCREMENT, app_id INTEGER NOT NULL, kind TEXT NOT NULL, name TEXT DEFAULT '', role TEXT DEFAULT '', value TEXT DEFAULT '', class_nn TEXT DEFAULT '', acc_path TEXT DEFAULT '', menu_path TEXT DEFAULT '', alt_keys TEXT DEFAULT '', shortcut TEXT DEFAULT '', cmd_id INTEGER DEFAULT 0, pos_order INTEGER DEFAULT 0, depth INTEGER DEFAULT 0, x INTEGER DEFAULT 0, y INTEGER DEFAULT 0, w INTEGER DEFAULT 0, h INTEGER DEFAULT 0, rel_x REAL DEFAULT 0, rel_y REAL DEFAULT 0, rel_w REAL DEFAULT 0, rel_h REAL DEFAULT 0, states TEXT DEFAULT '', findtext TEXT DEFAULT '', hits INTEGER DEFAULT 0, source_title TEXT DEFAULT '');
CREATE TABLE usage_element (id INTEGER PRIMARY KEY AUTOINCREMENT, win_id INTEGER NOT NULL, app_id INTEGER NOT NULL, signature TEXT NOT NULL, name TEXT, role TEXT, x INTEGER, y INTEGER, w INTEGER, h INTEGER, rel_x REAL, rel_y REAL, rel_w REAL, rel_h REAL, pattern TEXT, verified INTEGER DEFAULT 0, seen_count INTEGER DEFAULT 0, click_count INTEGER DEFAULT 0, access_count INTEGER DEFAULT 0, dwell_ms INTEGER DEFAULT 0, score REAL DEFAULT 0, promoted INTEGER DEFAULT 0, element_id INTEGER DEFAULT 0, first_ts TEXT, last_ts TEXT, UNIQUE(win_id, signature));
CREATE TABLE usage_event (id INTEGER PRIMARY KEY AUTOINCREMENT, ts TEXT, tick INTEGER, app_id INTEGER, win_id INTEGER, kind TEXT, token TEXT, data TEXT, automated INTEGER DEFAULT 0);
CREATE TABLE usage_transition (id INTEGER PRIMARY KEY AUTOINCREMENT, prefix_hash TEXT NOT NULL, prefix_text TEXT NOT NULL, prefix_len INTEGER NOT NULL, next_token TEXT NOT NULL, next_kind TEXT, next_data TEXT, support INTEGER DEFAULT 0, accepted INTEGER DEFAULT 0, last_ts TEXT, UNIQUE(prefix_hash, next_token));
CREATE TABLE vs_action (  id INTEGER PRIMARY KEY AUTOINCREMENT,  ts TEXT, tick INTEGER,  kind TEXT,  win_id INTEGER NOT NULL DEFAULT 0,  app_id INTEGER NOT NULL DEFAULT 0,  element_id INTEGER NOT NULL DEFAULT 0,  x INTEGER, y INTEGER,  label TEXT, detail TEXT);
CREATE TABLE vs_element (  id INTEGER PRIMARY KEY AUTOINCREMENT,  win_id INTEGER NOT NULL DEFAULT 0,  app_id INTEGER NOT NULL DEFAULT 0,  x INTEGER, y INTEGER, w INTEGER, h INTEGER,  rel_x REAL, rel_y REAL, rel_w REAL, rel_h REAL,  bin_text TEXT,  ocr_text TEXT,  score REAL NOT NULL DEFAULT 0,  clicks INTEGER NOT NULL DEFAULT 0,  accesses INTEGER NOT NULL DEFAULT 0,  tier INTEGER NOT NULL DEFAULT 0,  promoted INTEGER NOT NULL DEFAULT 0,  first_seen TEXT, last_seen TEXT, review_state TEXT NOT NULL DEFAULT 'unreviewed', review_note TEXT NOT NULL DEFAULT '', reviewed_at TEXT NOT NULL DEFAULT '',  UNIQUE(win_id, x, y, w, h));
CREATE TABLE vs_sequence (  id INTEGER PRIMARY KEY AUTOINCREMENT,  sig TEXT NOT NULL UNIQUE,  steps TEXT,  count INTEGER NOT NULL DEFAULT 0,  length INTEGER NOT NULL DEFAULT 0,  first_seen TEXT, last_seen TEXT);
CREATE TABLE win (  id          INTEGER PRIMARY KEY AUTOINCREMENT,  app_id      INTEGER NOT NULL REFERENCES app(id),  name        TEXT NOT NULL,  raw_title   TEXT,  first_seen  TEXT,  last_seen   TEXT,  total_ms    INTEGER NOT NULL DEFAULT 0,  activations INTEGER NOT NULL DEFAULT 0,  UNIQUE(app_id, name));
CREATE TABLE win_session (  id          INTEGER PRIMARY KEY AUTOINCREMENT,  win_id      INTEGER NOT NULL REFERENCES win(id),  app_id      INTEGER NOT NULL,  hwnd        INTEGER,  raw_title   TEXT,  start_ts    TEXT,  end_ts      TEXT,  duration_ms INTEGER NOT NULL DEFAULT 0,  day         TEXT,  hour        INTEGER,  x INTEGER, y INTEGER, w INTEGER, h INTEGER);
CREATE INDEX idx_uiel_app ON ui_element(app_id);
CREATE INDEX idx_uiel_name ON ui_element(app_id, name);
CREATE INDEX ix_alog_qa ON study_answer_log(qa_id);
CREATE INDEX ix_chrome_archive_time ON chrome_history_archive(visit_time DESC);
CREATE INDEX ix_chrome_archive_title ON chrome_history_archive(title);
CREATE UNIQUE INDEX ix_clink ON study_concept_link(from_id,to_id,relation);
CREATE INDEX ix_clip_hash ON clip_history(hash);
CREATE INDEX ix_clip_ts   ON clip_history(ts);
CREATE UNIQUE INDEX ix_concept_name ON study_concept(norm_name);
CREATE INDEX ix_elem_name ON element(name);
CREATE INDEX ix_feat_win ON mouse_feature(win_id);
CREATE INDEX ix_insight_query ON query_insight(query_id);
CREATE INDEX ix_key_event_min ON key_event(win_id,minute_key,ts,id);
CREATE INDEX ix_key_min ON key_snapshot(minute_key);
CREATE INDEX ix_key_win ON key_snapshot(win_id);
CREATE INDEX ix_link_query ON query_link(query_id);
CREATE INDEX ix_mouse_min ON mouse_snapshot(minute_key);
CREATE INDEX ix_mouse_win ON mouse_snapshot(win_id);
CREATE INDEX ix_passage_src ON study_passage(source_id);
CREATE UNIQUE INDEX ix_qa_fp ON qa_item(fingerprint);
CREATE INDEX ix_qa_open ON qa_item(archived, answer);
CREATE INDEX ix_sess_day ON win_session(day);
CREATE INDEX ix_sess_win ON win_session(win_id);
CREATE INDEX ix_snap_cycle ON snap_entry(cycle_id);
CREATE INDEX ix_snap_excluded ON snap_entry(is_excluded);
CREATE INDEX ix_snap_exclusion_active ON snap_exclusion(active,kind);
CREATE INDEX ix_snap_path  ON snap_entry(image_path);
CREATE INDEX ix_snap_title ON snap_entry(title);
CREATE INDEX ix_snap_url   ON snap_entry(url);
CREATE INDEX ix_snap_win   ON snap_entry(win_id);
CREATE INDEX ix_snip_sig ON snip(signature);
CREATE INDEX ix_usage_element_score ON usage_element(score DESC);
CREATE INDEX ix_usage_element_win ON usage_element(win_id);
CREATE INDEX ix_usage_event_id ON usage_event(id DESC);
CREATE INDEX ix_usage_event_token ON usage_event(token);
CREATE INDEX ix_usage_transition_prefix ON usage_transition(prefix_hash, support DESC);
CREATE INDEX ix_vs_action_ts ON vs_action(ts);
CREATE INDEX ix_vs_elem_tier ON vs_element(tier);
CREATE INDEX ix_vs_elem_win ON vs_element(win_id);
CREATE INDEX ix_win_app ON win(app_id);
CREATE TABLE IF NOT EXISTS fan_store(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS fan_migration(role TEXT PRIMARY KEY,source TEXT,signature TEXT,counts TEXT);
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY,at TEXT NOT NULL,kind TEXT NOT NULL,subject TEXT NOT NULL,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY,prompt TEXT NOT NULL,status TEXT NOT NULL,response TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,mode TEXT NOT NULL DEFAULT 'chat',history TEXT NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS records(name TEXT PRIMARY KEY,kind TEXT NOT NULL,description TEXT NOT NULL,tags TEXT NOT NULL,usage TEXT NOT NULL,examples TEXT NOT NULL,content TEXT NOT NULL,metadata TEXT NOT NULL,revision INTEGER NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS revisions(name TEXT NOT NULL,revision INTEGER NOT NULL,content TEXT NOT NULL,metadata TEXT NOT NULL,at TEXT NOT NULL,PRIMARY KEY(name,revision));
